#!/bin/bash
# SCA_MIN_SECONDS=21600
# HRGen-1K, all 1000 prompts, FLUX.1-dev shared sampler: SCA and AReA (paired).
# Protocol: every row of hrgen1k.jsonl (1000 ids; Aesthetic-4K development prompts included, as in AReA, arXiv 2610.17227, Sec. 4).
# Clone of hold_eval/z910_eval_sigma191.sh: constancy_rope eval.py + scripts/eval_extra.py with the main 4K metric flags,
# no references (HRGen-1K has none), so no FID/KID terms,
# scripts/paired_bootstrap.py (2000 draws, seed 0). Generated by /scratch/09032/saini_2/sca/code/eval195_20261020/make_eval_tasks.py.
# Release only after: every task of hold_hrgen1k_dev (a194_hd_*) in done/.
# Gate (no side effects, never sleeps): every method needs one PNG plus a complete JSON for all 1000 ids; otherwise the task
# parks a copy of itself in hold_eval and exits 3 at once. A CUDA OOM from co-tenant GPU processes republishes it (exit 75).
# Outputs: /scratch/09032/saini_2/sca/eval/hrgen1k_dev/ ; CSV summaries copied to results/hrgen1k_dev/ with SHA256SUMS. Not committed.
set -uo pipefail
export HF_HOME=/scratch/09032/saini_2/tmp/hf TORCH_HOME=/scratch/09032/saini_2/tmp/torch HF_HUB_OFFLINE=1 XDG_CACHE_HOME=/scratch/09032/saini_2/tmp/cache OMP_NUM_THREADS=8
unset CROPE_TRANSFORMER CROPE_ROPE
Q=/scratch/09032/saini_2/sca/taskq; NAME=z968_eval_hrgen1k_dev.sh; S=/scratch/09032/saini_2/sca; P=/work/09032/saini_2/vista/Projects/Exploration/Scale_Covariant_Attention
CR=/work/09032/saini_2/vista/Projects/Exploration/constancy_rope; E=$S/eval/hrgen1k_dev; R=$P/results/hrgen1k_dev; RES=4096x4096; N=1000
PR=/scratch/09032/saini_2/sca/hrgen1k.jsonl; REFS=none
PY=/work/09032/saini_2/vista/library/uv-envs/sca/bin/python; PYM=/work/09032/saini_2/vista/library/uv-envs/sca-metrics/bin/python
SPEC='sca_nb|0|/scratch/09032/saini_2/sca/out/hrgen/sca_nb/4096x4096;area|0|/scratch/09032/saini_2/sca/out/hrgen/area/4096x4096'
requeue(){ cp "$0" "$Q/pending/.$NAME.tmp.$$" && mv -f "$Q/pending/.$NAME.tmp.$$" "$Q/pending/$NAME" && echo "requeued $NAME to pending: $1"; }
park(){ [ -e "$Q/hold_eval/$NAME" ] || { cp "$0" "$Q/hold_eval/.$NAME.tmp.$$" && mv -f "$Q/hold_eval/.$NAME.tmp.$$" "$Q/hold_eval/$NAME"; }; echo "parked $NAME in hold_eval: $1"; }
recovered(){ if [ -e "$Q/failed/$NAME" ]; then mkdir -p $Q/recovered/a195_gate; mv "$Q/failed/$NAME" "$Q/recovered/a195_gate/$NAME.$(date +%Y%m%dT%H%M%S)"; fi; }
gate(){ python3 -I - "$PR" "$N" "$SPEC" "$RES" "${1:-}" <<'PY'
import glob, json, os, sys
prompts, n, spec, res, link = sys.argv[1:6]
ids = [json.loads(l)["id"] for l in open(prompts) if l.strip()]
assert len(ids) == int(n) == len(set(ids)), (len(ids), n)
bad, plan = 0, []
for item in spec.split(";"):
    method, seed, dirs = item.split("|"); miss = 0
    for i in ids:
        pngs = [p for d in dirs.split(",") for p in glob.glob(f"{d}/{glob.escape(i)}_*seed{seed}.png")]
        ok = len(pngs) == 1
        if ok:
            try:
                meta = json.load(open(pngs[0][:-4] + ".json"))
                ok = meta.get("complete") is True and str(meta["config"]["prompt_id"]) == i
            except Exception:
                ok = False
        if ok:
            plan.append((method, pngs[0]))
        else:
            miss += 1
    print(f"GATE {method} seed{seed}: {len(ids) - miss}/{len(ids)} complete", flush=True); bad += miss
if bad:
    sys.exit(1)
if link:
    for method, png in plan:
        d = os.path.join(link, method, res); os.makedirs(d, exist_ok=True)
        for src in (png, png[:-4] + ".json"):
            os.symlink(src, os.path.join(d, os.path.basename(src)))
    print("linked", len(plan), "images under", link, flush=True)
PY
}
if ! gate; then park "images missing; release again after: every task of hold_hrgen1k_dev (a194_hd_*) in done/"; exit 3; fi
if [ -e $E/DONE ]; then echo "already complete: $E"; recovered; exit 0; fi
if [ -e $E ]; then mv $E $E.partial_$(date +%Y%m%dT%H%M%S); fi
mkdir -p $E/paired
gate $E/root || { echo "GATE: linking failed"; exit 6; }
sha256sum $P/scripts/eval_extra.py $CR/scripts/eval.py $P/repro/evaluate_corrected.py $P/scripts/paired_bootstrap.py $PR  > $E/code_sha256.txt
run(){ "$@" 2>&1 | tee -a $E/run.log; local rc=${PIPESTATUS[0]}
  if [ $rc -ne 0 ]; then
    if grep -q -E 'OutOfMemoryError|CUDA out of memory|CUDA error: out of memory|cudaErrorMemoryAllocation' $E/run.log; then requeue "CUDA OOM from co-tenant GPU processes"; exit 75; fi
    echo "step failed rc=$rc: $*"; exit $rc
  fi; }
run $PYM $P/scripts/eval_extra.py --root $E/root --prompts $PR --out $E/extra --metrics ir,aesthetic,hpsv2,hpsv21,clipiqa,arniqa,is --reference-method area --device cuda --batch-size 16 --threads 8
run $PY $CR/scripts/eval.py --root $E/root --prompts $PR --reference-method area --res $RES --out $E/base --metrics clip,pickscore,musiq --device cuda
for pair in sca_nb:area; do a=${pair%%:*}; b=${pair#*:}
  run $PY -I $P/scripts/paired_bootstrap.py --method $a --reference $b --draws 2000 --out $E/paired/${a}_vs_${b}.csv $E/extra/extra_per_image.csv $E/base/per_image.csv
done
mkdir -p $R
cp $E/base/summary.csv $R/base_summary.csv && cp $E/extra/extra_summary.csv $R/extra_summary.csv && cp $E/paired/*.csv $R/ && true || { echo "copy to $R failed"; exit 8; }
for f in $E/base/paired_deltas.csv $E/extra/extra_paired_deltas.csv; do [ -s $f ] && cp $f $R/$(basename $f | sed 's/^paired/base_paired/; s/^extra_paired/extra_paired/'); done
(cd $R && sha256sum *.csv > SHA256SUMS)
date -u +%FT%TZ > $E/DONE; recovered
echo "DONE hrgen1k_dev: $E -> $R"
